import Foundation

@MainActor
enum InviteCodeManager {
    private static let activatedKey = "invite_code_activated"

    // 500 codes generated 2026-05-12. To regenerate, delete invite-codes-plaintext.txt
    // and run `swift scripts/generate-invite-codes.swift`.
    private static let _inviteCodesBlob = ""

    private static let validCodes: Set<String> = {
        let plaintext = _d(_inviteCodesBlob)
        guard !plaintext.isEmpty else {
            Log.error("InviteCodeManager: failed to decrypt invite codes blob")
            return []
        }
        return Set(plaintext.split(separator: "\n").map(String.init))
    }()

    static var isActivated: Bool {
        KeychainManager.read(key: activatedKey) != nil
    }

    /// Returns true if the code is valid; on success, persists activation in Keychain.
    @discardableResult
    static func tryActivate(with code: String) -> Bool {
        let normalized = code.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        guard validCodes.contains(normalized) else { return false }
        _ = KeychainManager.save(key: activatedKey, value: normalized)
        return true
    }
}
